// checkoutConversion.js - Fix conversion tracking for paid events
// Brainstem directive: paidEvents zero after many runs

const { logEvent } = require('./eventLogger');

module.exports = async function processCheckoutConversion(order) {
  if (!order || !order.id || !order.total) {
    console.warn('[checkoutConversion] Invalid order object');
    return { success: false, reason: 'invalid_order' };
  }

  // Ensure paid event is recorded
  const event = {
    type: 'paid_event',
    orderId: order.id,
    amount: order.total,
    currency: order.currency || 'USD',
    timestamp: new Date().toISOString(),
    customerId: order.customerId || 'anonymous'
  };

  try {
    await logEvent(event);
    console.log(`[checkoutConversion] Paid event logged for order ${order.id}`);
    return { success: true, event };
  } catch (err) {
    console.error('[checkoutConversion] Failed to log paid event:', err.message);
    return { success: false, reason: err.message };
  }
};
